    test('mergeStateOf: REST lowercase + boolean mergeable normalized', function () {
        var ms = mod.mergeStateOf({ mergeable: true, mergeable_state: 'clean' });
        assert.equal(ms.mergeable, true);
        assert.equal(ms.state, 'CLEAN');
    });
});

