        var result = run(fx);
        assert.equal(result.skipped, 1);
        assert.ok(result.log.some(function (l) { return l.indexOf('not mergeable') !== -1; }));
    });

    test('Part of #N links the PR WITHOUT closing semantics (awf#20)', function () {
