    }
    if (!runs.length) return 'none';
    var red = false, pending = false;
    runs.forEach(function (r) {
        var c = r.conclusion ? String(r.conclusion).toUpperCase() : null;
        var s = r.status ? String(r.status).toUpperCase() : null;
